"""Build a local, self-contained 2D review tool; never uploads source media."""
import json
import subprocess
from pathlib import Path

import imageio_ffmpeg
from pose_runtime import ROOT

OUT=ROOT/'outputs'/'pilot'
rows=[json.loads(line) for line in (OUT/'poses-tracked.jsonl').read_text().splitlines()]
meta=json.loads((ROOT/'work'/'source-metadata.json').read_text())
stats=json.loads((OUT/'render-stats.json').read_text())
frames=[{'frame':r['source_frame_index'],'people':[{'id':p['track_id'],'xy':p['keypoints_xy'][:23],
        'confidence':p['confidence'][:23],'bbox':p['bbox_xyxy'],'status':p['track_status']}
        for p in r['people'] if p['track_id']]} for r in rows]
subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-hide_banner','-loglevel','error','-y',
                '-ss','18','-i',meta['path'],'-t','12','-c:v','libx264','-preset','fast','-crf','18',
                '-pix_fmt','yuv420p','-c:a','aac','-b:a','192k','-movflags','+faststart',str(OUT/'source-reference.mp4')],check=True)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Systema · 2D pilot review</title><style>
*{box-sizing:border-box}body{margin:0;background:#111722;color:#eef2f8;font:15px system-ui}main{max-width:1550px;margin:30px auto;padding:0 24px}h1{font-size:26px;font-weight:600;margin:4px 0}p{color:#aebacc;line-height:1.5}header{margin-bottom:20px}.grid{display:grid;grid-template-columns:2fr 1fr;gap:20px}.panel{background:#1a2332;border:1px solid #324056;border-radius:12px;padding:16px}.stage{position:relative;aspect-ratio:16/9;background:#06080c}video{width:100%;height:100%;display:block}#overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}#illustration{display:block;width:100%;aspect-ratio:3/4;background:#0e1420}.controls{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:14px 0}button,a.button{background:#2d3b50;color:white;border:1px solid #52647d;border-radius:7px;padding:8px 12px;cursor:pointer;text-decoration:none}button:hover{background:#425571}input[type=range]{width:100%;accent-color:#fac04e}label{cursor:pointer}.tag{border:1px solid #56647a;border-radius:8px;padding:8px;font-size:13px}.note{font-size:13px;color:#ced7e5}.status{min-height:42px;color:#f6d493;font-size:13px;line-height:1.5}.links{display:flex;gap:16px;flex-wrap:wrap}a{color:#99d9ff}small{color:#aebacc}@media(max-width:850px){.grid{grid-template-columns:1fr}#illustration{max-height:620px}}
</style><main><header><small>SYSTEMA / MULTIPLE ATTACKERS</small><h1>Movement, one frame at a time</h1><p>12-second 2D pilot · source 18–30 seconds · 360 frames at 30 fps. Select participants to isolate an exchange or enlarge a pose.</p></header>
<div class="grid"><section class="panel"><div class="stage"><video id="source" src="source-reference.mp4" playsinline preload="auto"></video><canvas id="overlay" width="1920" height="1080"></canvas></div>
<div class="controls"><button id="play">Play</button><button id="prev">← Frame</button><button id="next">Frame →</button><button id="reset">Reset</button><span id="time"></span></div><input id="scrub" type="range" min="0" max="359" value="0" step="1" aria-label="Pilot frame"><div class="controls" id="participants"></div><div class="controls"><label><input id="bones" type="checkbox" checked> Skeleton overlay</label><label><input id="background" type="checkbox" checked> Source video</label><label>Confidence <select id="threshold"><option value="0.35">0.35</option><option value="0.55">0.55</option><option value="0.7">0.70</option></select></label></div><div id="status" class="status"></div>
<p class="note">Colors follow reviewed identity anchors. Joint positions are model estimates. During overlap, a high confidence score can still accompany the wrong limb. No hidden anatomy has been manually corrected.</p></section>
<section class="panel"><small>SELECTED PARTICIPANTS</small><h2 style="font-size:18px">Enlarged illustration</h2><canvas id="illustration" width="1080" height="1440"></canvas><div class="controls"><button id="save">Save transparent pose PNG</button></div><p class="note">Selected people share one image transform, preserving their relative 2D placement. This view has no reconstructed depth.</p></section></div>
<section class="panel" style="margin-top:20px"><div class="links"><a href="overlay-review.mp4">Overlay review video</a><a href="skeleton-alpha-prores4444.mov">ProRes 4444 with alpha</a><a href="enlarged-instructor.mp4">Instructor video</a><a href="manifest.json">Manifest</a><a href="poses-tracked.jsonl">Tracked pose data</a></div><p class="note">Review focus: 21–25 seconds contains severe overlap; 29–30 seconds contains cropping and lost participants. Transparent PNG sequences are supplied alongside this viewer.</p></section></main>
<script>
const frames=__FRAMES__,edges=__EDGES__,colors=__COLORS__;
const names=['Instructor · black shirt','Grey shirt','Blue shirt','White shirt'];
const video=document.getElementById('source'),overlay=document.getElementById('overlay'),illustration=document.getElementById('illustration');
const selected=new Set([1,2,3,4]);let frame=0;
names.forEach((name,i)=>{let label=document.createElement('label');label.className='tag';label.style.color=`rgb(${colors[i]})`;label.innerHTML=`<input type="checkbox" checked data-id="${i+1}"> ${name}`;document.getElementById('participants').append(label);label.firstChild.onchange=e=>{e.target.checked?selected.add(i+1):selected.delete(i+1);draw()}});
function skeleton(canvas,people,transform){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);const [scale,ox,oy]=transform;people.forEach(p=>{const xy=p.xy.map(a=>[a[0]*scale+ox,a[1]*scale+oy]),rgb=colors[p.id-1];function segment(a,b,width,color){c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.beginPath();c.moveTo(...xy[a]);c.lineTo(...xy[b]);c.stroke()};edges.forEach(([a,b])=>{let confidence=Math.min(p.confidence[a],p.confidence[b]);if(confidence<Number(document.getElementById('threshold').value))return;c.globalAlpha=confidence<.55?.49:1;segment(a,b,12,'#0c0f14');segment(a,b,7,`rgb(${rgb})`)});xy.forEach((a,j)=>{if(p.confidence[j]<Number(document.getElementById('threshold').value))return;c.globalAlpha=p.confidence[j]<.55?.49:1;c.fillStyle='#0c0f14';c.beginPath();c.arc(...a,7,0,2*Math.PI);c.fill();c.fillStyle=`rgb(${rgb})`;c.beginPath();c.arc(...a,4,0,2*Math.PI);c.fill()});c.globalAlpha=1})}
function draw(){const row=frames[frame],people=row.people.filter(p=>selected.has(p.id));document.getElementById('scrub').value=frame;document.getElementById('time').textContent=`Source ${(row.frame/30).toFixed(3)}s · frame ${row.frame}`;video.style.visibility=document.getElementById('background').checked?'visible':'hidden';skeleton(overlay,document.getElementById('bones').checked?people:[],[1,0,0]);if(people.length){let minx=Math.min(...people.map(p=>p.bbox[0])),miny=Math.min(...people.map(p=>p.bbox[1])),maxx=Math.max(...people.map(p=>p.bbox[2])),maxy=Math.max(...people.map(p=>p.bbox[3])),s=Math.min(920/(maxx-minx),1230/(maxy-miny));skeleton(illustration,people,[s,540-s*(minx+maxx)/2,720-s*(miny+maxy)/2])}else skeleton(illustration,[],[1,0,0]);let flags=people.filter(p=>p.status.some(s=>s.includes('ambiguous')||s.includes('gap')));let issues=[];if(row.frame>=630&&row.frame<=750)issues.push('Severe overlap: review instructor arms, shoulders and contact positions.');if(row.frame>=870)issues.push('Cropping / occlusion: some participants are not rendered.');if(flags.length)issues.push(`Tracking uncertainty: ${flags.map(p=>'T'+p.id).join(', ')}.`);document.getElementById('status').textContent=issues.join(' ')||'Estimated 2D poses. Check movement against the source footage.'}
function seek(i){video.pause();frame=Math.max(0,Math.min(359,i));video.currentTime=frame/30;draw()};document.getElementById('play').onclick=()=>video.paused?video.play():video.pause();document.getElementById('prev').onclick=()=>seek(frame-1);document.getElementById('next').onclick=()=>seek(frame+1);document.getElementById('reset').onclick=()=>seek(0);document.getElementById('scrub').oninput=e=>seek(Number(e.target.value));['bones','background','threshold'].forEach(id=>document.getElementById(id).onchange=draw);video.onplay=()=>document.getElementById('play').textContent='Pause';video.onpause=()=>document.getElementById('play').textContent='Play';video.onended=()=>seek(359);function tick(){if(!video.paused){frame=Math.min(359,Math.floor(video.currentTime*30+.01));draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);document.getElementById('save').onclick=()=>{let a=document.createElement('a');a.download=`systema-source-frame-${frames[frame].frame}.png`;a.href=illustration.toDataURL('image/png');a.click()};document.onkeydown=e=>{if(e.target.matches('input,select'))return;if(e.code==='ArrowRight'){e.preventDefault();seek(frame+1)}if(e.code==='ArrowLeft'){e.preventDefault();seek(frame-1)}if(e.code==='Space'){e.preventDefault();document.getElementById('play').click()}};draw();
</script></html>'''
html=html.replace('__FRAMES__',json.dumps(frames,separators=(',',':'))).replace('__EDGES__',json.dumps(stats['edges'])).replace('__COLORS__',json.dumps(stats['colors_rgb']))
(OUT/'index.html').write_text(html,encoding='utf-8')
print('Local review viewer saved.',flush=True)
